var e={"where.project":`Projekt`,"where.topic":`Thema`,"where.projectHelp":`Ein Projekt fasst die Themen eines Gegenstands zusammen. Seine CLAUDE.md und sein Gedächtnis gelten für alle seine Themen.`,"where.topicHelp":`Das Thema ist der Arbeitsordner dieser Sitzung: Harness arbeitet dort mit der CLAUDE.md und dem Gedächtnis des Themas sowie denen des Projekts und der globalen Ebene.`,"where.move":`Klicken, um die Sitzung in ein anderes Thema zu verschieben.`,"where.agent":`Agent`,"where.agentHelp":`Diese Sitzung läuft im Ordner eines Agents: Claude arbeitet dort mit der Rolle und dem Gedächtnis des Agents sowie mit denen des Themas, des Projekts und den globalen.`};export{e as default};